package dev.kelmagic.artifact;
import java.util.*;
import com.mojang.authlib.GameProfile;
import dev.kelmagic.*;
import dev.kelmagic.core.*;
import dev.kelmagic.server.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.monster.Phantom;
import net.minecraft.world.item.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.*;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.common.util.FakePlayerFactory;
public final class ArtifactBlockEntity extends BlockEntity {
    public UUID owner;public final Set<UUID> trusted=new LinkedHashSet<>();public double mana;public List<String> words=List.of();public UUID recording;public long recordingUntil,expires,lastStrike;public boolean active;
    public ArtifactBlockEntity(BlockPos p,BlockState s){super(ArtifactContent.ENTITY.get(),p,s);}
    public ArtifactBlock block(){return (ArtifactBlock)getBlockState().getBlock();}
    public boolean accepts(UUID id){return owner==null||owner.equals(id)||trusted.contains(id);}
    @Override public void onLoad(){super.onLoad();if(level instanceof ServerLevel l)ArtifactWorld.register(l,this);}
    @Override public void setRemoved(){if(level instanceof ServerLevel l)ArtifactWorld.unregister(l,worldPosition);super.setRemoved();}
    public void changed(){setChanged();if(level!=null){int fill=block().capacity==0?0:(int)Math.ceil(4*mana/block().capacity);var s=getBlockState();if(s.getValue(ArtifactBlock.FILL)!=fill)level.setBlock(worldPosition,s.setValue(ArtifactBlock.FILL,Math.clamp(fill,0,4)),2);level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),2);}}
    public void interact(ServerPlayer p){if(!ArtifactWorld.allowed(p,worldPosition)){p.displayClientMessage(Component.translatable("kelmagic.artifact.denied"),true);return;}if(owner==null){owner=p.getUUID();changed();}
        var name=p.getMainHandItem().get(net.minecraft.core.component.DataComponents.CUSTOM_NAME);
        if(owner.equals(p.getUUID())&&p.getMainHandItem().is(Items.NAME_TAG)&&name!=null){var other=p.getServer().getPlayerList().getPlayerByName(name.getString());if(other==null){p.displayClientMessage(Component.translatable("kelmagic.artifact.player_missing"),true);return;}if(trusted.contains(other.getUUID()))trusted.remove(other.getUUID());else if(trusted.size()<32)trusted.add(other.getUUID());changed();p.displayClientMessage(Component.translatable("kelmagic.artifact.access_updated",other.getName()),true);return;}
        if(!accepts(p.getUUID())){p.displayClientMessage(Component.translatable("kelmagic.artifact.denied"),true);return;}
        switch(block().kind){case BOWL,NIGHT,MUTE->transfer(p);case STRIKER->{if(level.getBlockEntity(worldPosition.below()) instanceof ArtifactBlockEntity be)be.strike();}case CRYSTAL->{recording=p.getUUID();recordingUntil=level.getGameTime()+400;words=List.of();changed();p.displayClientMessage(Component.translatable("kelmagic.artifact.record_ready"),true);}case ACCESS->p.displayClientMessage(Component.translatable("kelmagic.artifact.access_info",trusted.size()),true);case WARD->p.displayClientMessage(Component.translatable("kelmagic.artifact.portal_locked"),true);case GROVE->p.displayClientMessage(Component.translatable("kelmagic.artifact.grove_info"),true);default->{}}
    }
    private void transfer(ServerPlayer p){double amount;if(p.isShiftKeyDown()){amount=Math.min(5,Math.min(mana,Math.max(0,MagicServer.maximum(p)-p.getData(MagicAttachments.MANA).current())));mana-=amount;ArtifactRuntime.addMana(p,amount);}else{amount=ArtifactRules.deposit(mana,Math.min(5,p.getData(MagicAttachments.MANA).current()),block().capacity);if(!ArtifactRuntime.spend(p,amount))return;mana+=amount*.95;}changed();MagicServer.sync(p);p.displayClientMessage(Component.translatable("kelmagic.artifact.stored",String.format(java.util.Locale.ROOT,"%.1f",mana),block().capacity),true);if(amount>0)ArtifactVisuals.sound(p.serverLevel(),Vec3.atCenterOf(worldPosition),"mana_transfer",p.isShiftKeyDown()?1.1f:.85f);}
    public boolean capture(ServerPlayer p,List<String> tokens){if(block().kind!=ArtifactBlock.Kind.CRYSTAL||!p.getUUID().equals(recording)||level.getGameTime()>recordingUntil||p.distanceToSqr(Vec3.atCenterOf(worldPosition))>64)return false;if(tokens.isEmpty()||tokens.size()+words.size()>ArtifactRules.MAX_WORDS||tokens.stream().anyMatch(w->!KelLexicon.WORDS.containsKey(w))){p.displayClientMessage(Component.translatable("kelmagic.artifact.record_limit"),true);return true;}var next=new ArrayList<>(words);next.addAll(tokens);words=List.copyOf(next);changed();p.displayClientMessage(Component.translatable("kelmagic.artifact.recorded",String.join(" ",words)),true);ArtifactVisuals.sound(p.serverLevel(),Vec3.atCenterOf(worldPosition),"artifact_chime",.85f+words.size()*.15f);return true;}
    public boolean strike(){if(!(level instanceof ServerLevel l)||block().kind!=ArtifactBlock.Kind.CRYSTAL||owner==null||l.getGameTime()-lastStrike<20||!l.getBlockState(worldPosition.above()).is(ArtifactContent.STRIKER.get())||!(l.getBlockEntity(worldPosition.below()) instanceof ArtifactBlockEntity bowl)||bowl.block().kind!=ArtifactBlock.Kind.BOWL||!bowl.accepts(owner))return false;lastStrike=l.getGameTime();recording=null;recordingUntil=0;setChanged();var plan=SpellParser.plan(words);if(words.isEmpty()||words.size()>3||plan.effect()==SpellParser.Effect.GRAND||plan.effect()==SpellParser.Effect.UNDEFINED||plan.effect()==SpellParser.Effect.SELECTION_ONLY)return false;double cost=words.stream().mapToInt(String::length).sum();if(bowl.mana+1e-8<cost||ArtifactWorld.muted(l,Vec3.atCenterOf(worldPosition))||!ArtifactWorld.allowed(owner,l,worldPosition))return false;
        var fake=FakePlayerFactory.get(l,new GameProfile(owner,"KelCrystal"));fake.setPos(worldPosition.getX()+.5,worldPosition.getY()+.5,worldPosition.getZ()+.5);fake.removeAllEffects();fake.setHealth(fake.getMaxHealth());fake.setYRot(0);fake.setXRot(0);fake.getData(MagicAttachments.SESSION).clear();fake.setData(MagicAttachments.RESEARCH,dev.kelmagic.research.ResearchState.EMPTY);
        var aim=plan.area()?new SpellEffects.Aim(Vec3.atCenterOf(worldPosition),HitResult.Type.BLOCK,new BlockHitResult(Vec3.atCenterOf(worldPosition),Direction.UP,worldPosition.below(),false),null):randomAim(l,fake);if(aim==null)return false;bowl.mana-=cost;bowl.changed();ArtifactVisuals.sound(l,Vec3.atCenterOf(worldPosition),"crystal_strike",1);ArtifactVisuals.ring(l,Vec3.atCenterOf(worldPosition),.7,0x64d9e6,24);
        return ArtifactMagic.execute(fake,plan,words,cost,aim);
    }
    private SpellEffects.Aim randomAim(ServerLevel l,ServerPlayer fake){Vec3 start=Vec3.atCenterOf(worldPosition);for(int n=0;n<64;n++){double yaw=l.random.nextDouble()*Math.PI*2,yy=l.random.nextDouble()*1.6-.8;Vec3 dir=new Vec3(Math.cos(yaw),yy,Math.sin(yaw)).normalize();start=Vec3.atCenterOf(worldPosition).add(dir.scale(.75));Vec3 end=start.add(dir.scale(Math.min(24,Config.RANGE.get())));var hit=l.clip(new ClipContext(start,end,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,fake));if(hit.getType()==HitResult.Type.BLOCK&&!hit.getBlockPos().equals(worldPosition)&&!hit.getBlockPos().equals(worldPosition.below())&&!hit.getBlockPos().equals(worldPosition.above())&&l.hasChunkAt(hit.getBlockPos())&&ArtifactWorld.allowed(owner,l,hit.getBlockPos())){Vec3 v=hit.getLocation().subtract(fake.getEyePosition());fake.setYRot((float)(Math.toDegrees(Math.atan2(v.z,v.x))-90));fake.setXRot((float)-Math.toDegrees(Math.atan2(v.y,v.horizontalDistance())));return new SpellEffects.Aim(hit.getLocation(),HitResult.Type.BLOCK,hit,null);}}return null;}
    public static void tick(Level level,BlockPos pos,BlockState state,ArtifactBlockEntity be){if(!(level instanceof ServerLevel l))return;long now=l.getGameTime();var kind=be.block().kind;if(kind==ArtifactBlock.Kind.BRIDGE||kind==ArtifactBlock.Kind.ROOT_WALL){if(now>=be.expires)l.removeBlock(pos,false);return;}
        if(now%20!=0)return;be.active=false;
        if(kind==ArtifactBlock.Kind.MUTE&&be.mana>=1){be.mana-=1;be.active=true;be.changed();}
        if(kind==ArtifactBlock.Kind.NIGHT&&be.mana>=.25){var sleepers=l.players().stream().filter(p->p.isSleeping()&&p.distanceToSqr(Vec3.atCenterOf(pos))<=144).toList();if(!sleepers.isEmpty())for(var phantom:l.getEntitiesOfClass(Phantom.class,new AABB(pos).inflate(20))){phantom.setTarget(null);Vec3 v=phantom.position().subtract(Vec3.atCenterOf(pos)).normalize().scale(.8);phantom.setDeltaMovement(v.add(0,.2,0));be.mana=Math.max(0,be.mana-.25);be.active=true;be.changed();ArtifactVisuals.line(l,Vec3.atCenterOf(pos),phantom.position(),0xb98ce7);if(be.mana<.25)break;}}
        if(kind==ArtifactBlock.Kind.GROVE&&l.getBlockState(pos.below()).is(dev.kelmagic.content.MagicDreams.GRASS.get()))for(var p:l.players())if(p.distanceToSqr(Vec3.atCenterOf(pos))<=25&&p.isAlive()&&!p.isSpectator()&&p.getPersistentData().getLong("KelGroveManaAt")!=now){p.getPersistentData().putLong("KelGroveManaAt",now);ArtifactRuntime.addMana(p,.1);be.active=true;}
        var current=l.getBlockState(pos);if(current.getBlock()==be.block()&&current.getValue(ArtifactBlock.POWERED)!=be.active&&kind!=ArtifactBlock.Kind.STRIKER)l.setBlock(pos,current.setValue(ArtifactBlock.POWERED,be.active),2);
        if(be.active&&now%100==0&&kind==ArtifactBlock.Kind.NIGHT)ArtifactVisuals.sound(l,Vec3.atCenterOf(pos),"dream_guard",1);
        if(be.active&&kind==ArtifactBlock.Kind.MUTE&&!state.getValue(ArtifactBlock.POWERED))ArtifactVisuals.sound(l,Vec3.atCenterOf(pos),"silence_fall",.7f);
        if(be.active)ArtifactVisuals.ring(l,Vec3.atCenterOf(pos).add(0,.3,0),.55,kind==ArtifactBlock.Kind.MUTE?0xb28ce4:0x6ce4cb,12);
    }
    @Override protected void saveAdditional(CompoundTag t,HolderLookup.Provider provider){super.saveAdditional(t,provider);if(owner!=null)t.putUUID("Owner",owner);var users=new ListTag();trusted.forEach(u->users.add(StringTag.valueOf(u.toString())));t.put("Trusted",users);t.putDouble("Mana",ArtifactRules.finite(mana,block().capacity));var ws=new ListTag();words.forEach(w->ws.add(StringTag.valueOf(w)));t.put("Words",ws);t.putLong("Expires",expires);}
    @Override protected void loadAdditional(CompoundTag t,HolderLookup.Provider provider){super.loadAdditional(t,provider);owner=t.hasUUID("Owner")?t.getUUID("Owner"):null;trusted.clear();for(var x:t.getList("Trusted",Tag.TAG_STRING)){if(trusted.size()>=32)break;try{trusted.add(UUID.fromString(x.getAsString()));}catch(IllegalArgumentException ignored){}}mana=ArtifactRules.finite(t.getDouble("Mana"),block().capacity);words=t.getList("Words",Tag.TAG_STRING).stream().map(Tag::getAsString).filter(KelLexicon.WORDS::containsKey).limit(3).toList();expires=t.getLong("Expires");recording=null;}
    @Override public CompoundTag getUpdateTag(HolderLookup.Provider p){return saveWithoutMetadata(p);}
    @Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}
}
